def find_first_battery(charges, target):
    first = 0
    last = len(charges) - 1
    found = -1
    while first <= last:
        middle = (first + last) // 2
        charge = charges[middle]
        matches = charge == target
        if matches:
            found = middle
            last = middle - 1
        elif charge < target:
            first = middle + 1
        else:
            last = middle - 1
    return found
